// Parse QA Verdict — Retry (EACH mode)
// Robustly extract/parse the model's JSON verdict. Filesystem-safe.
// Also trims away any lingering request payloads so big base64 doesn’t flow downstream.

const j   = { ...$json };
const bin = $binary || {};

// Trim potential heavy fields that might have slipped past a "Drop … Payload" step
delete j.qaRequestBody;
delete j.requestBody;
delete j.contents;
delete j.systemInstruction;

// ---- config / thresholds ----
const isMock =
  !!j.__testMode ||
  !!j.__allowTinyImage ||
  String(j.modelVersion || '').toLowerCase().includes('mock');

// Allow downstream to tune acceptance threshold; default sane baseline
const minPoseScore = Number.isFinite(Number(j.qaMinPoseScore)) ? Number(j.qaMinPoseScore) : 0.70;

// ---- helpers ----
function findText(obj){
  if (!obj || typeof obj !== 'object') return null;
  if (Array.isArray(obj)){
    for (const v of obj){ const f = findText(v); if (f) return f; }
    return null;
  }
  if (typeof obj.text === 'string') return obj.text;
  if (obj.candidates) return findText(obj.candidates);
  if (obj.content)    return findText(obj.content);
  if (obj.parts)      return findText(obj.parts);
  if (obj[0])         return findText(obj[0]);
  return null;
}

function stripFences(s){
  if (!s) return '';
  let t = String(s).trim();
  t = t.replace(/^```[a-zA-Z]*\s*/,'').replace(/```$/,'').trim();
  t = t.replace(/```/g,'').trim();
  return t;
}

function tryParseJsonLoose(s){
  try { return JSON.parse(s); } catch (e) {}
  const start = s.indexOf('{');
  const end   = s.lastIndexOf('}');
  if (start >= 0 && end > start) {
    const sub = s.slice(start, end + 1);
    try { return JSON.parse(sub); } catch (e) {}
  }
  return null;
}

function boolish(v){
  if (typeof v === 'boolean') return v;
  if (typeof v === 'number')  return v !== 0;
  if (typeof v === 'string')  return /^(true|yes|y|1)$/i.test(v.trim());
  return false;
}

function num01(v, def=0){
  const n = Number(v);
  if (!Number.isFinite(n)) return def;
  return Math.max(0, Math.min(1, n));
}

// ---- extract, clean, parse ----
const rawText = findText(j) || '';
const cleaned = stripFences(rawText);
// cap how much we carry forward just in case the model rambles
const cleanedTrimmed = cleaned.slice(0, 5000);
const parsed  = tryParseJsonLoose(cleanedTrimmed);

// Default verdict if parsing fails
const fallback = {
  pose_score: 0,
  single_subject: false,
  extra_limbs: true,
  bg_white: false,
  leakage_from_pose_ref: true,
  cropped: true,
  notes: 'validator parse error'
};

// Normalize fields (coerce types, clamp ranges)
const vIn = parsed && typeof parsed === 'object' ? parsed : fallback;
const verdict = {
  pose_score:               num01(vIn.pose_score, 0),
  single_subject:           boolish(vIn.single_subject),
  extra_limbs:              boolish(vIn.extra_limbs),
  bg_white:                 boolish(vIn.bg_white),
  leakage_from_pose_ref:    boolish(vIn.leakage_from_pose_ref),
  cropped:                  boolish(vIn.cropped),
  notes:                    String(vIn.notes ?? '').slice(0, 500),
};

// Simple pass/fail suggestion (tune as needed via j.qaMinPoseScore)
const qaPass =
  verdict.pose_score >= minPoseScore &&
  verdict.single_subject &&
  !verdict.extra_limbs &&
  !verdict.leakage_from_pose_ref &&
  !verdict.cropped;

// ---- build output ----
const out = {
  ...j,
  // keep both generic & retry-scoped keys so downstream is flexible
  qaVerdict: verdict,
  qaVerdictRetry: verdict,
  qaRetryPass: qaPass,
  qaRetryThresholds: { minPoseScore },
  qaParseDebug: {
    mockMode: !!isMock,
    rawLength: rawText.length,
    cleanedLength: cleanedTrimmed.length,
    parsedOk: parsed != null,
  },
  qaRawText: cleanedTrimmed,
};

// ---- return SINGLE object (EACH mode) ----
return {
  json: out,
  binary: bin,
  pairedItem: ($input && $input.item && $input.item.pairedItem)
    ? $input.item.pairedItem
    : { item: (typeof $itemIndex === 'number' ? $itemIndex : 0) },
};

// Pose QA — Build Request — Retry (MINIMAL-PAIR, POSE-FIRST) — EACH mode
// Filesystem-safe: reads bytes via getBinaryDataBuffer using the CURRENT item index.
// Returns a SINGLE object and preserves pairedItem.

const j   = { ...$json };
const bin = $binary || {};
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

// (belt & suspenders) ensure we don't carry prior big fields
delete j.requestBody;
delete j.contents;
delete j.systemInstruction;

// ---- mock/test thresholds ----
const isMock =
  !!j.__testMode ||
  !!j.__allowTinyImage ||
  String(j.modelVersion || '').toLowerCase().includes('mock');

const minBytes = Number.isFinite(Number(j.minInlineBytes))
  ? Number(j.minInlineBytes)
  : (isMock ? 1 : 100);

// ---- helpers ----
function currentIndex(){
  const p = $input?.item?.pairedItem;
  if (p && typeof p.item === 'number') return p.item;
  if (typeof $itemIndex === 'number') return $itemIndex;
  return 0;
}
const idx = currentIndex();

async function readBuffer(key, { allowTiny = false } = {}) {
  if (!bin[key]) return null;
  try {
    const buf = await this.helpers.getBinaryDataBuffer(idx, key);
    if (!buf) return null;
    const ok = buf.length >= minBytes || (allowTiny && buf.length > 0);
    return ok ? buf : null;
  } catch { return null; }
}

function toB64(buf){ return buf.toString('base64'); }
function sha1(buf){ return require('crypto').createHash('sha1').update(buf).digest('hex'); }

function mimeFromExt(name=''){
  const n = String(name).toLowerCase();
  if (n.endsWith('.jpg') || n.endsWith('.jpeg')) return 'image/jpeg';
  if (n.endsWith('.webp')) return 'image/webp';
  if (n.endsWith('.png')) return 'image/png';
  return null;
}
function inferMime(b, fallback='image/png'){
  return b?.mimeType || mimeFromExt(b?.fileName || b?.fileNameOriginal) || fallback;
}

// ---- load binaries (mock-aware) ----
const poseBuf = await readBuffer('pose',      { allowTiny: isMock });
const outBuf  = await readBuffer('generated', { allowTiny: isMock });

if (!poseBuf) {
  const keys = Object.keys(bin || {});
  throw new Error(`QA (retry): missing pose reference (binary.pose). Present binary keys: [${keys.join(', ')}], idx=${idx}`);
}
if (!outBuf) {
  const keys = Object.keys(bin || {});
  throw new Error(`QA (retry): missing generated output (binary.generated). Present binary keys: [${keys.join(', ')}], idx=${idx}`);
}

// ---- expected pose number (debug only) ----
const expectedPose =
  (Number.isFinite(Number(j.poseNumber)) ? Number(j.poseNumber) : null) ??
  (Number.isFinite(Number(j.currentPoseNumber)) ? Number(j.currentPoseNumber) : null) ??
  (Number.isFinite(Number(j.__meta?.poseNumber)) ? Number(j.__meta.poseNumber) : null);

let poseNumFromName = null;
const poseName = bin.pose?.fileName || bin.pose?.fileNameOriginal || j.poseRefName || '';
const m = String(poseName).match(/pose[_\-]?(\d{1,3})/i);
if (m) poseNumFromName = Number(m[1]);

// ---- prompt content for QA model ----
const systemText = [
  'You are a strict pose validator.',
  'You will receive exactly two images:',
  '- IMAGE P: pose reference (first image).',
  '- OUTPUT: candidate to validate (second image).',
  'Return ONLY a minified JSON with fields: pose_score[0..1], single_subject[bool], extra_limbs[bool], bg_white[bool], leakage_from_pose_ref[bool], cropped[bool], notes[string].',
  'Evaluate pose/positioning vs IMAGE P only; ignore clothing/colors.'
].join('\n');

const parts = [
  { text: 'IMAGE P — POSE REFERENCE:' },
  { inlineData: { mimeType: inferMime(bin.pose),      data: toB64(poseBuf) } },
  { text: 'OUTPUT — IMAGE TO VALIDATE:' },
  { inlineData: { mimeType: inferMime(bin.generated), data: toB64(outBuf) } },
  { text: 'Return ONLY valid JSON like: {"pose_score":0.0,"single_subject":true,"extra_limbs":false,"bg_white":true,"leakage_from_pose_ref":false,"cropped":false,"notes":""}' }
];

const qaRequestBody = {
  systemInstruction: { role: 'system', parts: [{ text: systemText }] },
  contents: [{ role: 'user', parts }],
  generationConfig: { temperature: 0.0 }
};

// ---- debug payload ----
const qaDebug = {
  expectedPoseNumber: expectedPose,
  poseNumberFromFile: poseNumFromName,
  pose: {
    fileName: poseName || null,
    bytes: poseBuf.length,
    sha1: sha1(poseBuf),
  },
  generated: {
    fileName: bin.generated?.fileName || bin.generated?.fileNameOriginal || null,
    bytes: outBuf.length,
    sha1: sha1(outBuf),
  },
  runIndex: runIx,
  itemIndex: idx,
  minBytesUsed: minBytes,
  mockMode: !!isMock,
};

// ---- return SINGLE object (EACH mode) ----
return {
  json: { ...j, qaRequestBody, qaDebug },
  binary: bin,
  pairedItem: ($input && $input.item && $input.item.pairedItem)
    ? $input.item.pairedItem
    : { item: (typeof $itemIndex === 'number' ? $itemIndex : 0) },
};

// Extract Generated Image — RETRY (Pose) — EACH (STRICT, no cross-run fallback)
//
// Purpose: In the QA loop, bind the *current* attempt's pixels only.
// Policy: Do NOT scan other nodes/runs. If this item doesn't carry the image, fail fast.

const j = $json || {};
const b = $binary || {};
const itemIx = (typeof $itemIndex === 'number') ? $itemIndex : 0;

// ---------------- mock/prod awareness ----------------
const isMock =
  /mock/i.test(j?.modelVersion || "") ||
  j?.__testMode === true ||
  j?.__allowTinyImage === true;

const minInlineBytes = Number.isFinite(Number(j?.minInlineBytes))
  ? Number(j.minInlineBytes)
  : (isMock ? 1 : 100);

// ---------------- helpers ----------------
function pad2(n){ n = Number(n); return Number.isFinite(n) ? String(n).padStart(2,'0') : '01'; }

const poseNumberRaw =
  j.poseNumber ?? j.currentPoseNumber ?? j.__meta?.poseNumber ?? (itemIx + 1);
const poseNumber = Number.isFinite(Number(poseNumberRaw)) ? Number(poseNumberRaw) : (itemIx + 1);

const characterHash =
  j.characterHash || j.characterSpecs?.hash || j.__meta?.characterHash || 'nohash';

const qaRetryRaw = j.qaRetry ?? 1;
const qaRetry = Number.isFinite(Number(qaRetryRaw)) ? Number(qaRetryRaw) : 1;

// Note: filename is *stable* inside QA; attempt lives in __meta.generatedAttemptKey
const fileName = `characters_${characterHash}_pose${pad2(poseNumber)}.png`;

// ---------------- choose source (STRICT: current item only) ----------------
let srcKind = null;
let genBinary = null;

// 1) Prefer already normalized "generated"
if (b.generated) {
  // Re-wrap to enforce filename/mime (FS-safe; buffer copy is fine here)
  const buf = await this.helpers.getBinaryDataBuffer(0, 'generated');
  const mime = b.generated.mimeType || 'image/png';
  genBinary = await this.helpers.prepareBinaryData(buf, fileName, mime);
  srcKind = 'binary:generated';
}

// 2) Fallback: "generated_inline" created by the Drop node on this path
if (!genBinary && b.generated_inline) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'generated_inline');
  const mime = b.generated_inline.mimeType || 'image/png';
  genBinary = await this.helpers.prepareBinaryData(buf, fileName, mime);
  srcKind = 'binary:generated_inline';
}

// 3) LAST RESORT (mock only): accept JSON inline if it somehow remains
function findBase64(obj) {
  if (!obj || typeof obj !== 'object') return null;
  if (obj.inlineData?.data) return { data: obj.inlineData.data, mime: obj.inlineData.mimeType || 'image/png' };
  if (Array.isArray(obj)) { for (const v of obj){ const f = findBase64(v); if (f) return f; } return null; }
  if (obj.candidates) return findBase64(obj.candidates);
  if (obj.content)    return findBase64(obj.content);
  if (obj.parts)      return findBase64(obj.parts);
  if (obj[0])         return findBase64(obj[0]);
  return null;
}

if (!genBinary && isMock) {
  const found = findBase64(j);
  if (found?.data && String(found.data).length >= minInlineBytes) {
    const buf = Buffer.from(String(found.data), 'base64');
    genBinary = await this.helpers.prepareBinaryData(buf, fileName, found.mime || 'image/png');
    srcKind = 'json-inline(mock)';
  }
}

// Hard stop: never scan other nodes/runs here.
if (!genBinary) {
  throw new Error('Extract Generated Image — Retry (STRICT): no current-item generated/_inline binary found');
}

// ---------------- pass-through of related binaries ----------------
const poseBin = b.pose || null;
const charBin = b.character || null;

// ---------------- emit single object ----------------
return {
  json: {
    ...j,
    fileName,
    poseNumber,
    qaRetry,
    characterHash,
    __meta: {
      ...(j.__meta || {}),
      srcKind,                               // traceability
      generatedAttemptKey: `pose${pad2(poseNumber)}_try${qaRetry}.png`, // attempt lives in meta, not filename
    }
  },
  binary: {
    ...(charBin ? { character: charBin } : {}),
    ...(poseBin ? { pose: poseBin } : {}),
    generated: genBinary
  },
  pairedItem: ($input?.item?.pairedItem) ? $input.item.pairedItem : { item: itemIx }
};

// Prepare Gemini API request for POSE images (RETRY path).
// Mode: Run once for ALL items
// Goal: On retries, STOP copying the baseline stance. Place the SAME character (A) into the POSE (P).
// Adds: mock/test awareness (minInlineBytes), reattach-missing-binaries, pose-first image ordering.

const items = $input.all();
const out = [];

/* ---------- helpers ---------- */
function clampPose(n){ return Math.max(1, Math.min(12, Number(n || 0))); }
const POSE_REGEX = /(?:pose[_\- ]?(\d{1,2}))|[_\-\.](\d{1,2})(?:\D|$)|\/(\d{1,2})\.png$/i;
function parsePoseFromString(s){
  if (!s) return null;
  const m = String(s).match(POSE_REGEX);
  return m ? Number(m[1] || m[2] || m[3]) : null;
}

// Read binary for the specific item index
async function addInlineFromBinary(parts, label, bin, key, i, minLen){
  if (!bin || !bin[key]) return false;
  let buf;
  try { buf = await this.helpers.getBinaryDataBuffer(i, key); }
  catch { return false; }
  const base64 = buf?.toString('base64') || '';
  const threshold = Number.isFinite(minLen) ? minLen : 100;
  if (!base64 || base64.length < threshold) {
    throw new Error(`${label}: binary.${key} base64 too short (${base64.length} < ${threshold})`);
  }
  const mime = bin[key].mimeType || 'image/png';
  parts.push({ text: label });
  parts.push({ inlineData: { mimeType: mime, data: base64 } });
  return true;
}

function addInlineFromJsonBase64(parts, label, jKey, j, minLen){
  const b64 = j?.[jKey];
  const threshold = Number.isFinite(minLen) ? minLen : 100;
  if (!b64 || String(b64).length < threshold) return false;
  parts.push({ text: label });
  parts.push({ inlineData: { mimeType: 'image/png', data: String(b64) } });
  return true;
}

// Try to recover missing binaries by reading from other nodes
function safeItems(nodeName, rIx){ try { return $items(nodeName, 0, rIx) || []; } catch { return []; } }
function pullBinaryFromNodes(names, key, i, runIx){
  for (const name of names){
    for (const r of [runIx, 0]) {
      const arr = safeItems(name, r);
      if (!arr.length) continue;
      const it = arr[i] || arr[0];
      const bin = it?.binary?.[key];
      if (bin) return bin;
    }
  }
  return null;
}

/* ---------- main ---------- */
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

for (let i = 0; i < items.length; i++){
  const item = items[i];
  const j    = item.json || {};
  const bin  = { ...(item.binary || {}) };  // allow augmentation
  const cs   = j.characterSpecs || {};

  // Mock/test awareness for tiny placeholder images
  const isMock = /mock/i.test(j.modelVersion || j.requestBody?.modelVersion || '')
              || j.__testMode === true
              || j.__allowTinyImage === true;
  const minInlineBytes = Number.isFinite(Number(j.minInlineBytes))
    ? Number(j.minInlineBytes)
    : (isMock ? 1 : 100);

  // Best-effort reattach if binaries are missing (common when fan-out is JSON-only)
  if (!bin.pose) {
    bin.pose = pullBinaryFromNodes(['Download pose reference','Download a file (pose)'], 'pose', i, runIx) || bin.pose;
  }
  if (!bin.character) {
    bin.character =
      pullBinaryFromNodes(['Download base character','Download Base Character (R2)'], 'character', i, runIx) ||
      bin.character;
  }
  if (!bin.hair) {
    bin.hair = pullBinaryFromNodes(['Load Hairstyle Reference (R2/S3)'], 'hair', i, runIx) || bin.hair;
  }
  if (!bin.skin) {
    bin.skin = pullBinaryFromNodes(['Load Skin Swatch (R2/S3)'], 'skin', i, runIx) || bin.skin;
  }

  // ---- pose number resolution (robust) ----
  let poseNum = j.poseNumber ?? j.currentPoseNumber ?? j.__meta?.poseNumber ?? null;
  if (!Number.isFinite(Number(poseNum))) {
    const cands = [
      j.poseRefName, j.poseRefFilename, j.poseRef, j.poseFileName,
      j.poseRefUrl, j.poseUrl, j.posePath, j.characterPath,
      j.imageUrl, j.sourceUrl
    ];
    for (const c of cands){ const p = parsePoseFromString(c); if (Number.isFinite(p)){ poseNum = p; break; } }
  }
  if (!Number.isFinite(Number(poseNum))) throw new Error(`Prepare Gemini (pose — retry): poseNumber missing/invalid for item ${i}.`);
  poseNum = clampPose(poseNum);
  const nn = String(poseNum).padStart(2, '0');
  const poseLabel = `pose-${nn}`;

  // ---- user block (must exist) ----
  const userBlock = (j.posePromptBlock && String(j.posePromptBlock).trim()) || '';
  if (!userBlock) throw new Error(`Prepare Gemini (pose — retry): missing posePromptBlock for ${poseLabel} (item ${i}).`);

  // ---- retry awareness (cool sampling on last retry) ----
  const qaRetry     = Number.isFinite(Number(j.qaRetry)) ? Number(j.qaRetry) : 1;   // 1-based
  const maxRetries  = Number.isFinite(Number(j.maxPoseRetries)) ? Math.max(1, Number(j.maxPoseRetries)) : 2;
  const isLastRetry = qaRetry >= maxRetries;

  // Allow override via j.retryTemp; otherwise cool on last retry
  const plannedTemp = (typeof j.retryTemp === 'number')
    ? j.retryTemp
    : (isLastRetry ? 0.08 : 0.12);   // conservative floor on final retry

  // ---- build prompt parts in strict order ----
  const parts = [];

  // 0) Retry header to break anchoring to prior output
  const retryHeader = [
    'RETRY DIRECTIVES:',
    '• Discard prior output; regenerate from scratch following IMAGE P.',
    '• Place the SAME character from IMAGE A into the EXACT pose of IMAGE P.',
    '• COPY limb arrangement and silhouette from IMAGE P; DO NOT reuse any stance from IMAGE A.',
    '• RETAIN appearance from instructions/IMAGE A (hairstyle, skin tone, outfit). EXACTLY.',
        'Hair should be one unanimous shape with no flyaways, stray hairs, or strands.',
    '• Keep background pure white (#FFFFFF).'
  ].join('\n');
  parts.push({ text: retryHeader });

  // 1) Your existing pose instructions (locks/negatives)
  parts.push({ text: 'POSE INSTRUCTIONS (must be followed):' });
  parts.push({ text: userBlock });

  // 2) POSE reference FIRST to bias pose
  let haveP = false;
  haveP = await addInlineFromBinary.call(this, parts, 'IMAGE P — POSE REFERENCE (guide only; ignore appearance)', bin, 'pose', i, minInlineBytes);
  if (!haveP) haveP = addInlineFromJsonBase64(parts, 'IMAGE P — POSE REFERENCE (guide only; ignore appearance)', 'poseBase64', j, minInlineBytes);
  if (!haveP) throw new Error(`Prepare Gemini (pose — retry): Missing pose reference image (IMAGE P) for ${poseLabel} (item ${i}).`);

  // 3) APPEARANCE source SECOND
  let haveA = false;
  for (const k of ['character','image','data','file','reference','base']) {
    if (!haveA) {
      try {
        haveA = await addInlineFromBinary.call(this, parts, 'IMAGE A — APPEARANCE SOURCE (base character)', bin, k, i, minInlineBytes);
      } catch (e) {
        // In mock mode with a higher threshold, try next key before throwing
        if (!isMock) throw e;
      }
    }
  }
  if (!haveA) haveA = addInlineFromJsonBase64(parts, 'IMAGE A — APPEARANCE SOURCE (base character)', 'characterBase64', j, minInlineBytes);
  if (!haveA) throw new Error(`Prepare Gemini (pose — retry): Missing base character image (IMAGE A) for ${poseLabel} (item ${i}).`);

  // 4) Optional helpers (nudges only)
  try { await addInlineFromBinary.call(this, parts, 'IMAGE B — Hair reference (silhouette/part/length only)', bin, 'hair', i, minInlineBytes); } catch {}
  try { await addInlineFromBinary.call(this, parts, 'IMAGE C — Skin-tone swatch (colors only)', bin, 'skin', i, minInlineBytes); } catch {}

  // ---- system instruction (simple, strict) ----
  const systemText = [
    'You are a precise illustration tool.',
    'Honor the user instructions verbatim.',
    'Use attached images ONLY as described.',
    'Keep background pure white (#FFFFFF).'
  ].join('\n');

  // ---- generation config ----
  const generationConfig = {
    imageConfig: { aspectRatio: j.aspectRatio || '1:1' },
    temperature: plannedTemp,
  };

  // ---- request body ----
  const requestBody = {
    systemInstruction: { role: 'system', parts: [{ text: systemText }] },
    contents: [{ role: 'user', parts }],
    generationConfig,
    ...(j.model ? { model: j.model } : {}),
  };

  // ---- correlation/meta ----
  const characterHash = j.characterHash || cs.hash || 'nohash';
  const correlationId = `${characterHash}-POSE${poseNum}-RETRY${qaRetry}-${Date.now()}`;

  out.push({
    json: {
      ...j,
      poseNumber: poseNum,
      currentPoseNumber: poseNum,
      poseLabel,
      qaRetry,
      maxPoseRetries: maxRetries,
      generationConfig,
      requestBody,
      correlationId,
      __meta: {
        ...(j.__meta || {}),
        __prepPoseRetry: {
          isMock, minInlineBytes, runIx, itemIndex: i,
          haveP: !!haveP, haveA: !!haveA
        }
      }
    },
    binary: bin,
    pairedItem: { item: i },
  });
}

return out;

// Retry Builder (Prompt Tweaks)
// Mode: Run once for EACH item
// Build a stronger retry prompt from QA verdict; prepend to posePromptBlock; cool temperature; add entropy tag.

const j = $json || {};
const b = $binary || {};
const v = j.qaVerdict || {};

const add = [];

// --- Retry tag (entropy for dedup + tracing) ---
const retryN  = Number.isFinite(Number(j.qaRetry)) ? Number(j.qaRetry) : 1;
const entropy = Math.random().toString(36).slice(2, 8).toUpperCase();
add.push(`RETRY_ID: ${retryN}-${entropy}`);

// --- Order of authority and conflict resolution ---
add.push(
  'COMPLIANCE ORDER (highest→lowest): POSE LOCK (with IMAGE P) → Appearance Locks from IMAGE A → everything else.',
  'If any instruction conflicts, follow POSE LOCK first and treat IMAGE A only as appearance.'
);

// --- Pose-first hard lock ---
add.push(
  'POSE HARD LOCK:',
  '- Use IMAGE P ONLY for pose. Ignore the pose in IMAGE A entirely.',
  '- Limb positions and ground/air contact must MATCH IMAGE P exactly.'
);

// --- Anatomy/style stabilizers ---
add.push(
  'STYLE/ANATOMY LOCK:',
  '- Match IMAGE A style and proportions exactly (lines, textures, palette).',
  '- SAME head-to-body ratio and limb lengths as IMAGE A.',
  '- Keep silhouette thickness and camera distance consistent with IMAGE A.',
  '- Absolutely no cropping of head or feet. One child only.'
);

// --- Explicit appearance locks (prevents leakage from IMAGE P) ---
add.push(
  'APPEARANCE SOURCE LOCK:',
  '- Hair, face, skin tone, outfit type, outfit colors, and shoes must MATCH IMAGE A exactly.',
  '- Do NOT copy hair or clothing from IMAGE P.'
);

// --- Targeted QA corrections from verdict ---
function isBoolTrue(x){ return x === true; }
function isBoolFalse(x){ return x === false; }

if (isBoolFalse(v.single_subject) || isBoolTrue(v.extra_limbs)) {
  add.push('- Exactly ONE child; exactly 2 arms, 2 legs, 2 shoes.');
}
if (isBoolFalse(v.bg_white)) {
  add.push('- Background must be pure white (#FFFFFF); no gradients or textures.');
}
if (isBoolTrue(v.cropped)) {
  add.push('- Full body visible with small margin; do not crop head/hands/feet.');
}
if (isBoolTrue(v.leakage_from_pose_ref)) {
  add.push('- Ignore appearance in IMAGE P completely; use IMAGE P for pose ONLY.');
}
if (typeof v.pose_score === 'number' && v.pose_score < 0.9) {
  add.push('- FOLLOW IMAGE P EXACTLY for limb positions and contact; resolve conflicts in favor of POSE LOCK.');
}
if (v.notes) {
  add.push(`- Validator notes: ${String(v.notes).slice(0, 180)}`);
}

const retryBlock = add.join('\n') + '\n\n';

// --- Temperature: cool but >= 0.10 ---
const baseTemp =
  (j.generationConfig && typeof j.generationConfig.temperature === 'number')
    ? j.generationConfig.temperature
    : (typeof j.temperature === 'number' ? j.temperature : 0.25);

const retryTemp = Math.max(0.10, Number(baseTemp) - 0.10);

// --- Prepend to existing posePromptBlock ---
const current = String(j.posePromptBlock || '');

// Return ONE object (EACH mode)
return {
  json: {
    ...j,
    posePromptBlock: retryBlock + current,
    retryTemp,
    retryTag: `${retryN}-${entropy}`,
  },
  binary: b,
  ...( $input?.item?.pairedItem ? { pairedItem: $input.item.pairedItem } : {} ),
};

// Parse QA Verdict — EACH mode (strip code fences and robustly parse JSON)
// Input: Gemini QA HTTP response (text in candidates[].content.parts[].text)
// Output fields added: qaText (cleaned), qaVerdict (parsed JSON)

const j   = $json || {};
const bin = $binary || {};

// Find the model's text payload anywhere in the response
function findText(obj){
  if (!obj || typeof obj !== 'object') return null;
  if (Array.isArray(obj)){
    for (const v of obj){ const f = findText(v); if (f) return f; }
    return null;
  }
  if (typeof obj.text === 'string') return obj.text;
  if (obj.candidates) return findText(obj.candidates);
  if (obj.content)    return findText(obj.content);
  if (obj.parts)      return findText(obj.parts);
  if (obj[0])         return findText(obj[0]);
  return null;
}

function stripFences(s){
  if (!s) return '';
  let t = String(s).trim();
  // remove leading/trailing code fences like ```json ... ``` or ``` ...
  t = t.replace(/^```[a-zA-Z]*\s*/,'').replace(/```$/,'').trim();
  // also remove stray backticks if any remain
  t = t.replace(/```/g,'').trim();
  return t;
}

function tryParseJsonLoose(s){
  // Try direct JSON.parse first
  try { return JSON.parse(s); } catch {}
  // Try to extract the first {...} block
  const start = s.indexOf('{');
  const end   = s.lastIndexOf('}');
  if (start >= 0 && end > start) {
    const sub = s.slice(start, end + 1);
    try { return JSON.parse(sub); } catch {}
  }
  return null;
}

const rawText = findText(j) || '';
const cleaned = stripFences(rawText);

const verdict = tryParseJsonLoose(cleaned) || {
  pose_score: 0,
  single_subject: false,
  extra_limbs: true,
  bg_white: false,
  leakage_from_pose_ref: true,
  cropped: true,
  notes: 'validator parse error'
};

// Return ONE object (EACH mode)
return {
  json: { 
    ...j,
    qaText: cleaned,
    qaVerdict: verdict
  },
  binary: bin,
  ...( $input?.item?.pairedItem ? { pairedItem: $input.item.pairedItem } : {} ),
};

// Pose QA — Build Request — INITIAL (POSE-FIRST, MINIMAL-PAIR) — EACH
// Filesystem-safe; reads buffers for the CURRENT item; minimal 2-image payload.

// ---------- boot ----------
const jIn  = $json || {};
const bin  = $binary || {};
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

// ---------- slim any heavy fields (no base64 carried downstream) ----------
function stripInlineDataDeep(o){
  if (!o || typeof o !== 'object') return o;
  if (Array.isArray(o)) return o.map(stripInlineDataDeep);
  const x = {};
  for (const [k,v] of Object.entries(o)) {
    if (k === 'inlineData' && v && typeof v === 'object') {
      const mimeType = v.mimeType || undefined;
      x.inlineData = mimeType ? { mimeType } : {};
    } else {
      x[k] = stripInlineDataDeep(v);
    }
  }
  return x;
}
function slimJson(j){
  const c = { ...(j || {}) };
  delete c.qaRequestBody;
  delete c.requestBody;
  delete c.contents;
  delete c.systemInstruction;
  return stripInlineDataDeep(c);
}
const j = slimJson(jIn);

// ---------- mock/test thresholds ----------
const isMock =
  !!j.__testMode ||
  !!j.__allowTinyImage ||
  String(j.modelVersion || '').toLowerCase().includes('mock');

const minBytes = Number.isFinite(Number(j.minInlineBytes))
  ? Number(j.minInlineBytes)
  : (isMock ? 1 : 100);

// ---------- helpers ----------
function currentIndex(){
  const p = $input?.item?.pairedItem;
  if (p && typeof p.item === 'number') return p.item;
  if (typeof $itemIndex === 'number') return $itemIndex;
  return 0;
}
const idx = currentIndex();

async function readBuffer(key, { allowTiny=false } = {}){
  if (!bin[key]) return null;
  try {
    const buf = await this.helpers.getBinaryDataBuffer(idx, key);
    if (!buf) return null;
    const ok = buf.length >= minBytes || (allowTiny && buf.length > 0);
    return ok ? buf : null;
  } catch { return null; }
}
function toB64(buf){ return buf.toString('base64'); }
function sha1(buf){ return require('crypto').createHash('sha1').update(buf).digest('hex'); }
function mimeFromExt(name=''){
  const n = String(name).toLowerCase();
  if (n.endsWith('.jpg') || n.endsWith('.jpeg')) return 'image/jpeg';
  if (n.endsWith('.webp')) return 'image/webp';
  if (n.endsWith('.png')) return 'image/png';
  return null;
}
function inferMime(b, fallback='image/png'){
  return b?.mimeType || mimeFromExt(b?.fileName || b?.fileNameOriginal) || fallback;
}
function zpad(n, w=2){ const s=String(Math.max(0, Number(n)|0)); return s.length>=w?s:'0'.repeat(w-s.length)+s; }
function looksLikePoseName(name){
  const n = String(name||'').toLowerCase();
  if (/pose[_\-]?\d{1,3}\.(png|jpe?g|webp)$/.test(n)) return true;
  if (/^p[\-_]?\d{1,3}\.(png|jpe?g|webp)$/.test(n))   return true;
  return /(^|\/)pose(\.|_|-|$)/.test(n);
}

function safeItems(nodeName, rIx){ try { return $items(nodeName, 0, rIx) || []; } catch { return []; } }
function preferredIndex(arr){
  const p = $input?.item?.pairedItem?.item;
  const ix = (typeof p === 'number') ? p : (typeof $itemIndex === 'number' ? $itemIndex : 0);
  return (ix>=0 && ix<arr.length) ? ix : 0;
}
function getItemFromNode(nodeName, rIx){
  const arr = safeItems(nodeName, rIx);
