const POSE_REGEX = /(?:pose[_\- ]?(\d{1,2}))|[_\-\.](\d{1,2})(?:\D|$)|\/(\d{1,2})\.png$/i;
function parsePoseFromString(s){ if(!s) return null; const m=String(s).match(POSE_REGEX); return m?Number(m[1]||m[2]||m[3]):null; }

const POSE_PROMPT_MAP = {
  '1': `Walking step. Front foot forward and flat; rear heel slightly lifted. Torso upright, shoulders level. Natural counter-swing of arms (opposite arm forward to leading leg). Head forward; gaze ahead; gentle smile.`,
  '2': `Walking while looking higher. Front foot forward; rear heel lifted. Elbows softly bent; hands near torso (light fists). Chin raised; head tilted up/right; eyes above horizon. Torso upright; shoulders level.`,
  '3': `Standing and scanning the distance. Feet under hips, weight even. One hand forms a visor across the brow (palm down, fingers together, elbow angled forward); other arm relaxed at side. Head slightly right; gaze far ahead; cheerful.`,
  '4': `Floating/hovering. Both feet off ground, toes pointed downward; knees softly bent. Arms slightly out from sides (~30–45°), fingers relaxed. Torso upright; head forward; joyful. No running/walking motion.`,
  '5': `Walking while looking down. Front foot flat; rear heel subtly lifted. Arms relaxed with palms facing in, slight rearward swing. Chin tipped downward; eyes on ground a step ahead. Torso upright; shoulders level; curious (not sad).`,
  '6': `Jogging. Lead knee lifted; rear heel up. Elbows ~90°, hands light fists at mid-torso; opposite arm leads. Torso upright with slight forward lean; head forward; eyes ahead; focused happy smile. Side/Profile view.`,
  '7': `Sitting cross-legged and eating. Legs crossed; feet tucked. Torso upright. Both hands hold a simple, unbranded sandwich near the mouth; elbows close to body. Mouth in cheerful bite; eyes on sandwich or slightly forward.`,
  '8': `Crouching/inspect. Deep squat with feet flat, hips close to heels. Forearms rest on thighs; hands relaxed near knees. Head tilted down/forward; eyes focused on ground directly in front. Small “o” of wonder or soft smile; hair clear of face.`,
  '9': `Crawling, moving, happy. On hands and knees; leading hand reaching forward while opposite knee advances. Hips low; back long; torso ~30–45° above ground. Head slightly raised; eyes forward/down along path; wide happy smile.`,
  '10': `Surprised, looking up. Feet under hips; slight lean back. Elbows bent with open hands near mid-torso (no waving). Chin lifted; head tilted up; eyes wide above; small surprised “o”; eyebrows raised; shoulders level.`,
  '11': `Surprised (forward). Feet under hips; slight recoil. Elbows bent; hands open slightly out from body at rib height. Head forward; eyes wide straight ahead; small surprised “o”; eyebrows raised; shoulders level.`,
  '12': `Flying/gliding. Body airborne; legs trailing slightly back with toes pointed. Arms out ~30–45° for balance; fingers relaxed. Torso angled slightly upward; head forward; eyes ahead; joyful smile. No ground contact.`
};
const POSE_NEGATIVES = {
  '1': ['No jumping/airborne.', 'Rear heel must lift.', 'No same-side arm/leg forward together.'],
  '2': ['Head must tilt up.', 'No fully straight elbows.', 'No downward gaze.'],
  '3': ['No walking/jogging.', 'Visor palm faces down.', 'No hunched torso.'],
  '4': ['No feet touching ground.', 'No running stride.', 'Arms not clamped to sides.'],
  '5': ['No upward gaze.', 'Front foot stays flat.', 'No big arm swings/raised hands.'],
  '6': ['Not a flat-foot walk.', 'Add slight forward lean.', 'Hands not open waving.'],
  '7': ['No standing/kneeling.', 'No branding/crumbs/mess.', 'Elbows not flared wide.'],
  '8': ['Heels stay flat.', 'Hips must be near heels.', 'No hands on ground.'],
  '9': ['No standing/sitting.', 'One knee advances forward.', 'No pointing fingers.'],
  '10': ['Not looking forward/down.', 'Hands not above shoulders.', 'No forward lean.'],
  '11': ['Not looking up.', 'Only slight recoil (no lean back).', 'Hands open (no fists).'],
  '12': ['No ground contact.', 'Torso not angled downward.', 'Arms not straight overhead.']
};

function hairstyleLock(styleKey, color){
  const c = norm(styleKey);
  const base = [
    'CONSISTENT HAIRSTYLE LOCK:',
    '- Do not change cut, part side, length, or ear visibility.',
    '- Motion may deflect strands but silhouette/part/length stay unchanged.',
    '- Hair is a single, opaque, connected mass; no flyaways/halos.'
  ];
  const colorLine = color ? [`- Hair color: ${color} (do not recolor).`] : [];
  const map = {
    'side-part': ['- PART on character’s RIGHT (viewer’s LEFT); sweep LEFT.','- Both ears fully visible; no hair below ear top.','- Back follows skull curve; no straight “bob” hem.'],
    'ponytail': ['- One ponytail back; no loose face strands.'],
    'pigtails': ['- Two mid-height tails; solid masses; face/ears clear.'],
    'bun': ['- Single back/low bun; tidy front.'],
    'pom-poms': ['- Two high puffs; clean center part; each ≤30% head width; total ≤90%; no face overlap.'],
    'locs': ['- Grouped neatly; continuous outer outline; interior detail by tone/lines.'],
    'afro': ['- Even rounded halo; continuous silhouette; no pinholes.'],
    'straight-short': ['- Above-chin; outline hugs head; eyes/ears clear.'],
    'straight-medium': ['- To shoulders; kept behind shoulders.'],
    'straight-long': ['- Below shoulders; trails behind back; length fixed.'],
    'curly-short': ['- Compact halo; scalloped edge OK but continuous.'],
    'curly-medium': ['- Shoulder-level curls; keep continuous outline.'],
    'curly-long': ['- Long curls behind shoulders/back; no lace-like cutouts.']
  };
  return base.concat(colorLine, map[c]||[]).join('\n');
}

function clothingLock(cs){
  const type = norm(cs?.clothingStyle || '');
  if (type === 'dress') {
    return [
      'OUTFIT / CLOTHING LOCK:',
      '- Outfit MUST remain a DRESS (single-piece).',
      '- Do NOT replace with a T-shirt and shorts, pants, or layered outfits.',
      '- Keep the same dress silhouette as IMAGE A (short sleeves, A-line body); no waist seam or shorts hem visible.'
    ].join('\n');
  }
  return [
    'OUTFIT / CLOTHING LOCK:',
    '- Outfit MUST remain a short-sleeve T-SHIRT and SHORTS.',
    '- Do NOT replace with a dress, skirt, pants, or layered outfits.',
    '- Keep shorts length and T-shirt silhouette consistent with IMAGE A.'
  ].join('\n');
}

function buildFraming(poseNum){
  const airborne = (poseNum === 4 || poseNum === 12);
  return [
    'FRAMING & CONTACT:',
    '- Full body in frame; do not crop head/hands/feet.',
    airborne ? '- CONTACT: No feet touching ground; no grounded foot shadows.'
             : '- CONTACT: At least one foot clearly on ground as described; anatomically correct contact.',
    '- Perspective: mild 3/4 or straight-on; avoid extreme foreshortening.'
  ].join('\n');
}

function buildPoseLock(poseNum){
  const core = POSE_PROMPT_MAP[String(poseNum)] || '';
  const negs = POSE_NEGATIVES[String(poseNum)] || [];
  const lines = [
    `POSE LOCK — ID ${poseNum}`,
    core,
    'FOLLOW IMAGE P EXACTLY for limb positions, weight/ground contact, and hand orientation.',
    'If any instruction conflicts, this POSE LOCK (with IMAGE P) outranks all other guidance.'
  ];
  if (negs.length){ lines.push('POSE HARD NEGATIVES:'); for (const n of negs) lines.push('- ' + n); }
  return lines.join('\n');
}

// ---- pose number (use explicit fields, fallback to filename) ----
let poseNum = j.poseNumber ?? j.currentPoseNumber ?? j.__meta?.poseNumber ?? null;
if (!Number.isFinite(Number(poseNum))){
  const cands = [j.poseRefName, j.poseRefFilename, j.poseRef, j.poseFileName, j.poseRefUrl, j.poseUrl, j.posePath, j.imageUrl, j.sourceUrl, $binary?.pose?.fileName];
  for (const c of cands){ const p = parsePoseFromString(c); if (Number.isFinite(p)){ poseNum = p; break; } }
}
if (!Number.isFinite(Number(poseNum))) throw new Error('Build Pose Prompt: poseNumber missing/invalid.');
poseNum = clampPose(poseNum);

// ---- compose prompt (thin) ----
const cs = j.characterSpecs || {};
const subjectLimit = 'SUBJECT LIMIT: Exactly one child in frame — no duplicates, reflections, extra limbs, or extra bodies.';
const hairLock = hairstyleLock(cs.hairStyle || '', cs.hairColor || j.hairPromptMeta?.color || '');
const outfitLock = clothingLock(cs);
const skinLock = [
  'SKIN-TONE LOCK: Keep skin tone identical to base.',
  j.skinToneId ? `- Palette: ${j.skinToneId}` : null,
  j.skinHexBase ? `- Base hex: ${j.skinHexBase} (do not lighten/darken).` : null,
  j.skinColorLock ? `- ${j.skinColorLock}` : null,
  '- Maintain undertone; do not shift toward pink/gray/yellow; no freckles/blush unless requested.'
].filter(Boolean).join('\n');

const allowedProps = []; // if you use these later, fill from a map as before
const posePromptBlock = [
  'COMPLIANCE ORDER (highest → lowest): Subject Limit → POSE LOCK (with IMAGE P) → Outfit Lock → Hairstyle Lock → Skin Tone Locks.',
  subjectLimit,
  buildPoseLock(poseNum),
  buildFraming(poseNum),
  outfitLock,
  hairLock,
  skinLock,
  'PROPS: No props. Hands empty unless the pose description specifies otherwise.',
  '- Do NOT copy hair/outfit/colors from IMAGE P; IMAGE P is pose ONLY. All appearance comes from IMAGE A (and IMAGE B if provided).'
].filter(Boolean).join('\n\n');

// ---- minimal output JSON ----
const outJson = {
  amazonOrderId: j.amazonOrderId,
  characterHash: j.characterHash || j.characterSpecs?.hash || null,
  poseNumber: poseNum,
  currentPoseNumber: poseNum,
  poseRefName: $binary?.pose?.fileName || j.poseRefName || null,
  posePromptBlock,
  posePromptMeta: { poseNumber: poseNum, allowedProps, version: 'v1.2-pose-with-outfit-lock', source: 'pose-prompt-builder' }
};

return {
  json: outJson,
  binary: $binary,
  pairedItem: ($input?.item?.pairedItem) ? $input.item.pairedItem : { item: ($itemIndex ?? 0) },
};

// Resolve Pose Ref (IMAGE P) — EACH mode
// Emits: poseRefKey, poseRefUrl, poseNumber/currentPoseNumber, poseLabel, poseRefName

const j = { ...($json || {}) };
const b = $binary || {};
const itemIx = (typeof $itemIndex === 'number') ? $itemIndex : 0;

// 1) Base URL (normalize trailing slash)
const posesBase = String(
  j.posesPublicBase ||
  'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev/little-hero-assets/book-mvp-simple-adventure/characters/poses/'
).replace(/\/?$/, '/');

// 2) Pose number (clamp 1..12; prefer explicit fields, then __meta, then index+1)
function clamp(n){ const x = Number(n); return Number.isFinite(x) ? Math.max(1, Math.min(12, Math.floor(x))) : null; }
let poseNum =
  clamp(j.currentPoseNumber) ??
  clamp(j.poseNumber) ??
  clamp(j.__meta?.poseNumber) ??
  clamp(itemIx + 1) ?? 1;

const NN = String(poseNum).padStart(2, '0');

// 3) Filename pattern
// Default to the hyphen style (pose-01.png). You can override with j.poseRefPattern,
// e.g. 'pose-${NN}.png', 'pose${NN}.png', '${NN}.png', or '${N}.png'
const pattern = j.poseRefPattern || 'pose${NN}.png';
const refName = pattern
  .replace('${NN}', NN).replace('{NN}', NN)
  .replace('${N}', String(poseNum)).replace('{N}', String(poseNum));

// 4) Public URL
const poseRefUrl = `${posesBase}${refName}`;

// 5) Derive bucket-relative KEY from URL (strip protocol+host; then optional bucket prefix)
let poseRefKey = poseRefUrl.replace(/^https?:\/\/[^/]+\//, '');
// If your S3/R2 node uses bucketName = "little-hero-assets", the key must NOT include the bucket name
poseRefKey = poseRefKey.replace(/^little-hero-assets\//i, '');

// 6) Emit single object (EACH mode)
return {
  json: {
    ...j,
    poseNumber: poseNum,
    currentPoseNumber: poseNum,
    poseLabel: `pose${NN}`,
    poseRefName: refName,
    poseRefUrl,
    poseRefKey
  },
  binary: b,
  pairedItem: ($input && $input.item && $input.item.pairedItem) ? $input.item.pairedItem : { item: itemIx }
};

// Simulate the upstream order so you can test the pose loop without regenerating the base character.
// This mirrors production fields used by the prompt builder & QA.

// ---------- SIM CONFIG ----------
const SIM = {
  // Character + assets
  characterHash: '1567edfe9a2e96c5',
  totalPosesRequired: 2,                  // set 12 for full run
  assetsRoot: 'book-mvp-simple-adventure',
  orderAssetsPrefix: 'order-generated-assets',
  baseCharacterFilename: 'base-character.png',
  publicR2Url: 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev',
  posesPublicBase: 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev/little-hero-assets/book-mvp-simple-adventure/characters/poses/',
  get characterPath() { return `characters/${this.characterHash}`; },

  // Order/character knobs
  customerEmail: 'jeff@example.com',

  // These match what your prod prompt builder reads
  characterSpecs: {
    childName: 'Alex',
    skinTone: 'medium',
    hairColor: 'medium-brown',
    hairStyle: 'straight-short',
    age: 5,
    pronouns: 'she/her',
    favoriteColor: 'green',
    animalGuide: 'tiger',
    clothingStyle: 'dress',
  },

  bookSpecs: {
    title: 'Alex and the Adventure Compass',
    totalPages: 16,
    format: '8.5x8.5_softcover',
    bookType: 'animal-guide',
  },

  // Appearance locks used by your prompt nodes
  // (Build Dynamic Pose Prompt looks for these)
  hairStyleCanonical: 'straight-short',
  hairPromptMeta: {
    styleKey: 'straight-short',
    color: 'medium-brown',
    colorHex: '#B88751',                 // tweak as desired
  },
  skinToneId: 'medium',                  // optional palette id your builder may echo back
  skinHexBase: '#C88C5A',                // optional anchor color
  skinColorLock: '',                     // optional extra rule line

  // QA / retry policy knobs (read by retry/IF nodes)
  qaThreshold: 0.90,
  maxPoseRetries: 2,
};

// ---------- EMIT ORDER ----------
const now = new Date().toISOString();

const order = {
  amazonOrderId: 'SIM-ORDER-001',
  status: 'ai_generation_in_progress',
  orderDate: now,
  customerEmail: SIM.customerEmail,

  characterSpecs: SIM.characterSpecs,
  bookSpecs: SIM.bookSpecs,
  orderDetails: { quantity: 1 },

  aiGenerationStartedAt: now,
  posesGenerated: 0,
