  // critical derivations for downstream nodes
  characterHash: SIM.characterHash,
  characterPath: SIM.characterPath,
  assetsRoot: SIM.assetsRoot,
  orderAssetsPrefix: SIM.orderAssetsPrefix,
  baseCharacterFilename: SIM.baseCharacterFilename,
  publicR2Url: SIM.publicR2Url,

  // pose loop config
  totalPosesRequired: SIM.totalPosesRequired,
  posesPublicBase: SIM.posesPublicBase,
  templatePath: 'templates',

  // appearance-lock fields (mirrors prod)
  hairStyleCanonical: SIM.hairStyleCanonical,
  hairPromptMeta: SIM.hairPromptMeta,
  skinToneId: SIM.skinToneId,
  skinHexBase: SIM.skinHexBase,
  skinColorLock: SIM.skinColorLock,

  // QA / retry policy
  qaThreshold: SIM.qaThreshold,
  maxPoseRetries: SIM.maxPoseRetries,
};

return [{ json: order }];

// Expand to N Poses — ALL mode (JSON-only fan-out; no binaries)
// Uses the first incoming item as the source and emits N JSON copies with pose fields.

const item = $input.first() || { json: {}, binary: {} };
const j = item.json || {};

const rawTotal = Number(j.totalPosesRequired);
const total = Number.isFinite(rawTotal) ? Math.max(1, Math.floor(rawTotal)) : 12;

const out = [];
for (let n = 1; n <= total; n++) {
  out.push({
