// Generate Character Hash — EACH mode
// Deterministic, normalized hash from characterSpecs.
// IMPORTANT: In EACH mode, return a single object (not an array).

const j  = { ...($json || {}) };
const b  = $binary || {};
const cs = j.characterSpecs || {};

function intOr(v, d){ const n = Number.parseInt(v, 10); return Number.isFinite(n) ? n : d; }

// Create a normalized character specification object for hashing
const characterHashSpec = {
  skinTone:       (cs.skinTone || 'medium'),
  hairColor:      (cs.hairColor || 'brown'),
  hairStyle:      (cs.hairStyle || 'short/straight'),
  age:            intOr(cs.age, 5),
  pronouns:       (cs.pronouns || 'they/them'),
  favoriteColor:  (cs.favoriteColor || 'blue'),
  animalGuide:    (cs.animalGuide || 'dog'),
  clothingStyle:  (cs.clothingStyle || 't-shirt and shorts'),
};

// Order keys for stable hashing
const orderedSpec = Object.keys(characterHashSpec)
  .sort()
  .reduce((acc, k) => { acc[k] = characterHashSpec[k]; return acc; }, {});

// Generate a deterministic hash from the character specifications
const crypto = require('crypto');
const hashString = JSON.stringify(orderedSpec);
const characterHash = crypto.createHash('sha256').update(hashString).digest('hex').substring(0, 16);

// Add character hash and normalized specs to order data
const out = {
  ...j,
  characterSpecs: cs,             // preserve original specs
  characterHash,                  // short deterministic id
  characterHashSpec: orderedSpec, // normalized spec used for hashing
  characterPath: `characters/${characterHash}`,
  templatePath: 'templates',
};

// Optional: log for debug
console.log(`Generated character hash: ${characterHash}`);

// EACH mode => return a SINGLE object
return {
  json: out,
  binary: b,
  // preserve pairing if present (helps downstream merges)
  ...(($input && $input.item && $input.item.pairedItem) ? { pairedItem: $input.item.pairedItem } : {})
};

// Restore Metadata After Upload — EACH mode
// Merges the S3/R2 upload result (this item) back onto the original image context
// from "Process Gemini API response and extract generated image" (or equivalent extractor).
// Returns a SINGLE object (EACH mode).

const uploadJson = { ...($json || {}) };
const fallbackBin = $binary || {};
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;
const itemIx = (typeof $itemIndex === 'number') ? $itemIndex : 0;

// -------- helpers --------
function safeItems(nodeName, rIx) {
  try { return $items(nodeName, 0, rIx) || []; } catch { return []; }
}

// Try multiple likely extractor node names (handles base/pose variants)
const SOURCE_NODES = [
  'Process Gemini API response and extract generated image',
  'Extract Generated Image',
  'Extract Generated Image — Retry',
  'Extract BASE CHARACTER image from Gemini response — EACH mode',
];

function getFirstExistingSourceItem() {
  for (const name of SOURCE_NODES) {
    let arr = safeItems(name, runIx);
    if (!arr.length) arr = safeItems(name, 0);
    if (arr.length) {
      const picked = arr[itemIx] || arr[0];
      if (picked) return { item: picked, nodeName: name, runUsed: (arr === safeItems(name, runIx) ? runIx : 0) };
    }
  }
  return { item: null, nodeName: null, runUsed: null };
}

function pick(obj, keys = []) {
  for (const k of keys) {
    if (obj && obj[k] != null && obj[k] !== '') return obj[k];
  }
  return undefined;
}

// -------- locate original context --------
const { item: originalItem, nodeName: sourceNode, runUsed } = getFirstExistingSourceItem();
if (!originalItem || !originalItem.json) {
  throw new Error('Restore Metadata: could not locate original extractor item (check node name list or runs).');
}

const originalJson = originalItem.json || {};
const originalBin  = originalItem.binary || fallbackBin;

// Pull out a few common upload fields for convenience
const uploadedUrl = pick(uploadJson, ['url', 'fileUrl', 'publicUrl', 'Location', 'location', 'signedUrl']);
const uploadedKey = pick(uploadJson, ['key', 'fileKey', 's3Key', 'r2Key', 'Key']);

// -------- build merged json --------
const out = {
  ...originalJson,
  // surface helpful pointers if present (do not overwrite with undefined)
  ...(uploadedUrl ? { generatedUploadUrl: uploadedUrl } : {}),
  ...(uploadedKey ? { generatedUploadKey: uploadedKey } : {}),
  // keep the full upload payload under a namespaced key
  uploadResult: {
    ...(originalJson.uploadResult || {}),
    ...uploadJson,
  },
  __meta: {
    ...(originalJson.__meta || {}),
    restoreAfterUpload: {
      sourceNode: sourceNode || 'unknown',
      sourceRunIx: runUsed,
      itemIndex: itemIx,
      surfacedUrl: Boolean(uploadedUrl),
      surfacedKey: Boolean(uploadedKey),
    },
  },
};

// Binaries: keep the original item’s binaries (the upload result rarely carries any)
const binOut = originalBin || fallbackBin || {};

// -------- emit (EACH mode => single object) --------
return {
  json: out,
  binary: binOut,
  // Prefer the original pairing; else fall back to current
  pairedItem:
    (originalItem.pairedItem)
      ? originalItem.pairedItem
      : (($input && $input.item && $input.item.pairedItem) ? $input.item.pairedItem : { item: itemIx }),
};

// Extract BASE CHARACTER image from Gemini response — EACH mode
// Accepts tiny images in mock/test mode; enforces min size in production.

const root = $json || {};
const b = $binary || {};
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;
const itemIx = (typeof $itemIndex === 'number') ? $itemIndex : 0;

/* ---------- helpers ---------- */
function pickRoot(r){
  if (r?.body?.candidates) return r.body;
  if (r?.response?.candidates) return r.response;
  if (r?.data?.candidates) return r.data;
  return r;
}

function firstInlineFromParts(parts){
  if (!Array.isArray(parts)) return null;
  for (const p of parts){
    const id = p?.inlineData?.data || p?.inline_data?.data;
    if (id) {
      return {
        b64: String(id),
        mime: p?.inlineData?.mimeType || p?.inline_data?.mime_type || 'image/png',
        path: 'content.parts.inlineData'
      };
    }
  }
  return null;
}

function findInlineImage(r){
  const cand = r?.candidates?.[0];
  if (cand?.content?.parts){
    const got = firstInlineFromParts(cand.content.parts);
    if (got) return got;
  }
  if (Array.isArray(cand?.content) && cand.content[0]?.parts){
    const got = firstInlineFromParts(cand.content[0].parts);
    if (got) return got;
  }
  // Deep fallback
  const stack = [r];
  while (stack.length) {
    const cur = stack.pop();
    if (!cur || typeof cur !== 'object') continue;
    const d = cur?.inlineData?.data || cur?.inline_data?.data;
    if (d) {
      return {
        b64: String(d),
        mime: cur?.inlineData?.mimeType || cur?.inline_data?.mime_type || 'image/png',
        path: '...inlineData/inline_data (fallback)'
      };
    }
    for (const k of Object.keys(cur)) {
      const v = cur[k];
      if (v && typeof v === 'object') stack.push(v);
    }
  }
  return null;
}

